content.text:
=== INIT ===
th/init-email-login": {
        "post": {
          "summary": "E-Mail-Anmeldung starten",
          "description": "Fordert einen Einmalcode per E-Mail an. Bei nicht berechtigten Adressen oder innerhalb der Sperrfrist erfolgt keine Fehlermeldung.",
          "tags": [
            "Authentifizierung"
          ],
          "requestBody": {
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "client": {
                      "type": "string",
                      "enum": [
                        "dashboard",
                        "app"
                      ],
                      "description": "The client to login to."
                    },
                    "emailAddress": {
                      "type": "string",
                      "format": "email",
                      "description": "The email address of the user."
                    },
                    "schoolSlug": {
                      "type": "string",
                      "minLength": 3,
                      "maxLength": 56,
                      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",
                      "description": "The slug of the school to login to."
                    }
                  },
                  "required": [
                    "client",
                    "emailAddress",
                    "schoolSlug"
                  ]
                }
              }
            }
          },
          "responses": {
            "201": {
              "description": "Anfrage angenommen"
            },
            "400": {
              "description": "Bad Request",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "error": {
                        "type": "object",
                        "properties": {
                          "type": {
                            "type": "string",
                            "enum": [
                              "invalidInput"
                            ]
                          },
                          "timestamp": {
                            "type": "string",
                            "format": "date-time"
                          },

=== COMPLETE ===
th/complete-email-login": {
        "post": {
          "summary": "E-Mail-Anmeldung abschließen",
          "description": "Validiert den per E-Mail erhaltenen Einmalcode und setzt bei Erfolg ein Session-Cookie.",
          "tags": [
            "Authentifizierung"
          ],
          "requestBody": {
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "client": {
                      "type": "string",
                      "enum": [
                        "dashboard",
                        "app"
                      ],
                      "description": "The client to login to."
                    },
                    "emailAddress": {
                      "type": "string",
                      "format": "email",
                      "description": "The email address of the user."
                    },
                    "schoolSlug": {
                      "type": "string",
                      "minLength": 3,
                      "maxLength": 56,
                      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",
                      "description": "The slug of the school to login to."
                    },
                    "otp": {
                      "type": "string",
                      "minLength": 1,
                      "description": "The OTP received from the email login page."
                    }
                  },
                  "required": [
                    "client",
                    "emailAddress",
                    "schoolSlug",
                    "otp"
                  ]
                }
              }
            }
          },
          "responses": {

observation.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.text();
  const i = txt.indexOf("th/init-email-login\": {");
  console.log("=== INIT ===");
  console.log(txt.slice(i, i + 2400));
  const c = txt.indexOf("th/complete-email-login\": {");
  console.log("=== COMPLETE ===");
  console.log(txt.slice(c, c + 1800));
})();
' 2>&1 | head -120
